    {"slug":"feijao-de-corda-ipiranga","name":"Feijão de Corda Original · Ipiranga","cuisine":"Nordestina · brasileira","description":"Restaurante de cozinha nordestina na Avenida Nazaré, com baião de dois, arrumadinho, carnes e peixes; a casa informa seu endereço e especialidades no site.","description_source_url":"https://feijaodecordaipiranga.brs.com.br/","address":"Avenida Nazaré, 400, Ipiranga, São Paulo - SP","neighborhood":"Ipiranga","website_url":"https://feijaodecordaipiranga.brs.com.br/","menu_url":"https://feijaodecordaipiranga.brs.com.br/cardapio.html","source_url":"https://feijaodecordaipiranga.brs.com.br/","price_basis":"menu_items_only","price_source_url":"https://ipiranganews.inf.br/wp-content/uploads/Jornal-Ipiranga-News-1239.pdf"}
  ]$$::jsonb as items
), restaurants as (
  select * from jsonb_to_recordset((select items from payload)) as x(
    slug text, name text, cuisine text, description text, description_source_url text,
    address text, neighborhood text, website_url text, menu_url text, source_url text,
    price_basis text, price_source_url text
  )
)
insert into public.curated_restaurants
  (slug,name,cuisine,description,description_source_url,address,neighborhood,city,state,website_url,menu_url,source_url,price_basis,price_source_url,status,verified_at)
select slug,name,cuisine,description,description_source_url,address,neighborhood,'São Paulo','SP',website_url,menu_url,source_url,price_basis,price_source_url,'published',now()
from restaurants
on conflict (slug) do update set
  name=excluded.name,cuisine=excluded.cuisine,description=excluded.description,
  description_source_url=excluded.description_source_url,address=excluded.address,
  neighborhood=excluded.neighborhood,city=excluded.city,state=excluded.state,
  website_url=excluded.website_url,menu_url=excluded.menu_url,source_url=excluded.source_url,
  price_basis=excluded.price_basis,price_source_url=excluded.price_source_url,
  status='published',verified_at=now(),updated_at=now();

