insert into public.curated_restaurant_photos
  (restaurant_id,image_url,attribution,license_name,license_url,source_page_url,is_primary,verified_at)
select r.id,p.image_url,p.attribution,p.license_name,p.license_url,p.source_page_url,true,now()
from photos p join public.curated_restaurants r on r.slug=p.slug
on conflict (restaurant_id,image_url) do update set
  attribution=excluded.attribution,license_name=excluded.license_name,license_url=excluded.license_url,
  source_page_url=excluded.source_page_url,is_primary=true,verified_at=now();

