  ]$$::jsonb as items
), menu as (
  select * from jsonb_to_recordset((select items from menu_payload)) as x(
    slug text,name text,description text,price_brl numeric,price_basis text,service_mode text,
    source_url text,source_checked_at timestamptz,price_status text
  )
)
insert into public.curated_menu_items
  (restaurant_id,name,description,price_brl,price_basis,service_mode,source_url,source_checked_at,price_status)
select r.id,m.name,m.description,m.price_brl,m.price_basis,m.service_mode,m.source_url,m.source_checked_at,m.price_status
from menu m join public.curated_restaurants r on r.slug=m.slug
on conflict (restaurant_id,name,price_basis,service_mode,source_checked_at) do update set
  description=excluded.description,price_brl=excluded.price_brl,source_url=excluded.source_url,
  price_status=excluded.price_status,updated_at=now();

commit;
